	x.BootFunctions = d.stMAPast_FuncDef_bool()
	x.AppTypes = d.stSPStructType()
	x.Errors = d.stSTypeError()
	d.hookProgramProgramErrors(x)
	x.revision = int(d.w.Int())
	x.bootGraph = d.stPbootGraphCache()
	x.ContextType = d.stType()
	x.StdlibModuleScopes = d.stMAstring_PScope()
	x.files = d.stSPFileAnalysis()
	x.filesByKey = d.stMAstring_PFileAnalysis()
	x.unindexedImpls = d.stMAstring_MAstring_bool()
	x.results = d.stPprogramResults()
	d.stsync_Mutex(&x.demandsMu)
	x.demands = d.stPprogramDemands()
	x.entryDemands = d.stPprogramDemands()
	x.implUses = d.stPkeptImplUses()
